import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent, type LlmCallRecord } from "../../types";
import { llmCallToConversationEvent } from "../../utils/llm-calls";
import { LlmCallEventInfo } from "./LlmCallEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({
    title,
    onClose,
    children,
  }: {
    title: string;
    onClose: () => void;
    children: React.ReactNode;
  }) => (
    <div>
      <h1>{title}</h1>
      <button data-testid="event-details-close" onClick={onClose}>
        Close
      </button>
      {children}
    </div>
  ),
}));

function makeRecord(overrides: Partial<LlmCallRecord>): LlmCallRecord {
  return {
    id: "r1",
    timestamp: 100,
    purpose: null,
    request_model: "gpt-4o",
    response_model: "gpt-4o-2024-08-06",
    input_tokens: 120,
    output_tokens: 8,
    latency_ms: 1250,
    time_to_first_token_ms: null,
    tool_names: [],
    gated_tool_names: [],
    response_tool_names: [],
    prompt_messages: null,
    response_messages: null,
    is_error: false,
    error_message: null,
    ...overrides,
  };
}

function makeEvent(overrides: Partial<LlmCallRecord>): ConversationEvent {
  return llmCallToConversationEvent(makeRecord(overrides));
}

describe("LlmCallEventInfo", () => {
  it("renders the model and the usage line", () => {
    renderWithProviders(<LlmCallEventInfo event={makeEvent({})} onClose={vi.fn()} />);

    expect(screen.getByText("LLM call")).toBeInTheDocument();
    expect(screen.getByText("gpt-4o-2024-08-06")).toBeInTheDocument();
    expect(screen.getByTestId("llm-call-usage")).toHaveTextContent("1.3 s · 120 → 8 tokens");
  });

  describe("tool tags", () => {
    const event = makeEvent({
      tool_names: ["lock_card", "set_fields"],
      gated_tool_names: ["submit_travel_notice"],
      response_tool_names: ["lock_card"],
    });

    it("renders every declared and gated tool", () => {
      renderWithProviders(<LlmCallEventInfo event={event} onClose={vi.fn()} />);

      const tools = screen.getByTestId("llm-call-tools");
      expect(tools).toHaveTextContent("lock_card");
      expect(tools).toHaveTextContent("set_fields");
      expect(tools).toHaveTextContent("submit_travel_notice");
    });

    it("styles tools used in the response differently from merely declared ones", () => {
      renderWithProviders(<LlmCallEventInfo event={event} onClose={vi.fn()} />);

      const usedTag = screen.getByText("lock_card").parentElement;
      const declaredTag = screen.getByText("set_fields").parentElement;
      expect(usedTag).not.toBeNull();
      expect(declaredTag).not.toBeNull();
      expect(usedTag?.className).not.toBe(declaredTag?.className);
    });

    it("marks gated tools with their own testid", () => {
      renderWithProviders(<LlmCallEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.getByTestId("llm-call-gated-tool")).toHaveTextContent("submit_travel_notice");
    });
  });

  describe("prompt and response sections", () => {
    it("renders both sections when messages are present", () => {
      const event = makeEvent({
        prompt_messages: [{ role: "user", content: "lock my card" }],
        response_messages: [{ role: "assistant", content: "On it." }],
      });

      renderWithProviders(<LlmCallEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.getByTestId("llm-call-prompt")).toHaveTextContent("[user]");
      expect(screen.getByTestId("llm-call-prompt")).toHaveTextContent("lock my card");
      expect(screen.getByTestId("llm-call-response")).toHaveTextContent("[assistant]");
      expect(screen.getByTestId("llm-call-response")).toHaveTextContent("On it.");
    });

    it("hides both sections when messages are empty", () => {
      renderWithProviders(
        <LlmCallEventInfo
          event={makeEvent({ prompt_messages: null, response_messages: null })}
          onClose={vi.fn()}
        />,
      );

      expect(screen.queryByTestId("llm-call-prompt")).not.toBeInTheDocument();
      expect(screen.queryByTestId("llm-call-response")).not.toBeInTheDocument();
    });
  });

  it("renders the error alert with the message for failed calls", () => {
    renderWithProviders(
      <LlmCallEventInfo
        event={makeEvent({ is_error: true, error_message: "rate limited" })}
        onClose={vi.fn()}
      />,
    );

    expect(screen.getByRole("alert")).toHaveTextContent("This LLM call failed:");
    expect(screen.getByText("rate limited")).toBeInTheDocument();
  });

  it("renders nothing when the event carries no llm_call record", () => {
    const event: ConversationEvent = {
      __typename: "ConversationEvent",
      id: "1",
      conversationEventType: ConversationEventType.LlmCallRecorded,
      name: "llm_call_recorded",
      actionText: "",
      flowId: "",
      stepId: "",
      slotValue: null,
      timestamp: new Date().toISOString(),
      originalTimestamp: 0,
      metadata: { parseData: undefined },
    };

    const { container } = renderWithProviders(<LlmCallEventInfo event={event} onClose={vi.fn()} />);

    expect(container).toBeEmptyDOMElement();
  });
});
